import{_ as t,o,c as s,a2 as i}from"./chunks/framework.BEUshCVJ.js";const d=JSON.parse('{"title":"安装与升级","description":"","frontmatter":{},"headers":[],"relativePath":"zh/troubleshooting/install.md","filePath":"zh/troubleshooting/install.md","lastUpdated":1792881664000}'),l={name:"zh/troubleshooting/install.md"};function a(n,e,r,p,c,h){return o(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="安装与升级" tabindex="-1">安装与升级 <a class="header-anchor" href="#安装与升级" aria-label="Permalink to &quot;安装与升级&quot;">​</a></h1><p>本页用于 Scoop 无法安装或升级 MeetCue、Windows 拦截 MeetCue，或升级后设置似乎丢失的情况。</p><h2 id="download" tabindex="-1">Scoop 无法下载 MeetCue <a class="header-anchor" href="#download" aria-label="Permalink to &quot;Scoop 无法下载 MeetCue {#download}&quot;">​</a></h2><p><strong>可能原因</strong></p><ol><li>无法访问 <code>github.com</code>，或需要代理。</li><li>添加 bucket 时地址填错了。</li></ol><p><strong>检查</strong></p><ol><li>运行 <code>scoop bucket list</code>，查看 <code>meetcue</code> bucket 的地址。</li><li>在浏览器中打开 <code>https://github.com/Amazingkenneth/meetcue/releases</code>。</li></ol><p><strong>解决</strong></p><ol><li><p>重新添加 bucket：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scoop bucket rm meetcue</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scoop bucket add meetcue https:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">github.com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Amazingkenneth</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">meetcue</span></span></code></pre></div></li><li><p>需要代理时，用 <code>scoop config proxy proxy.example.com:8080</code> 为 Scoop 设置代理。</p></li></ol><p><strong>仍未解决？</strong> <a href="https://github.com/Amazingkenneth/meetcue/issues/new?template=bug.yml" target="_blank" rel="noreferrer">提交 Issue</a>，附上 Scoop 的完整输出。</p><h2 id="hash" tabindex="-1">Scoop 提示哈希不匹配 <a class="header-anchor" href="#hash" aria-label="Permalink to &quot;Scoop 提示哈希不匹配 {#hash}&quot;">​</a></h2><p><strong>可能原因</strong></p><ol><li>下载中断，或被代理修改。</li><li>本地 bucket 版本过旧。</li></ol><p><strong>检查</strong></p><ol><li>运行 <code>scoop update</code> 刷新所有 bucket。</li></ol><p><strong>解决</strong></p><ol><li><p>清除缓存的下载后重试：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scoop cache rm meetcue</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scoop install meetcue</span></span></code></pre></div></li></ol><p><strong>仍未解决？</strong> <a href="https://github.com/Amazingkenneth/meetcue/issues/new?template=bug.yml" target="_blank" rel="noreferrer">提交 Issue</a>，附上 Scoop 的完整输出。</p><h2 id="blocked" tabindex="-1">Windows 或杀毒软件拦截 MeetCue <a class="header-anchor" href="#blocked" aria-label="Permalink to &quot;Windows 或杀毒软件拦截 MeetCue {#blocked}&quot;">​</a></h2><p><strong>可能原因</strong></p><ol><li>本版本没有代码签名，SmartScreen 可能提示“未知发布者”。</li><li>杀毒软件把新出现、下载量少的程序标记为可疑。</li><li>公司策略只允许运行经批准的程序。</li></ol><p><strong>检查</strong></p><ol><li>记下具体提示内容以及是哪个程序弹出的。</li></ol><p><strong>解决</strong></p><ol><li>遇到 SmartScreen 时，如果你信任这个下载，点击 <strong>更多信息 › 仍要运行</strong>。Release 页面列出了 zip 的 SHA-256 哈希，可以核对。</li><li>向杀毒软件厂商报告误报，或请 IT 部门放行 <code>MeetCue.exe</code>。</li><li>如果公司策略拦截所有未签名程序，在提供签名版本之前 MeetCue 无法在该电脑上运行。</li></ol><p><strong>仍未解决？</strong> <a href="https://github.com/Amazingkenneth/meetcue/issues/new?template=bug.yml" target="_blank" rel="noreferrer">提交 Issue</a>。</p><h2 id="webview2" tabindex="-1">提示缺少 WebView2 <a class="header-anchor" href="#webview2" aria-label="Permalink to &quot;提示缺少 WebView2 {#webview2}&quot;">​</a></h2><p><strong>可能原因</strong></p><ol><li>Microsoft Edge WebView2 运行时被卸载或从未安装（<a href="/meetcue/zh/troubleshooting/error-codes#mc-sys-001">MC-SYS-001</a>）。</li></ol><p><strong>检查</strong></p><ol><li>在 <strong>设置 › 应用 › 已安装的应用</strong> 中查找 <strong>Microsoft Edge WebView2 Runtime</strong>。</li></ol><p><strong>解决</strong></p><ol><li>从微软官网下载并安装 Evergreen 版 WebView2 运行时，然后重新启动 MeetCue。</li></ol><p><strong>仍未解决？</strong> <a href="https://github.com/Amazingkenneth/meetcue/issues/new?template=bug.yml" target="_blank" rel="noreferrer">提交 Issue</a>。</p><h2 id="settings-lost" tabindex="-1">升级后设置不见了 <a class="header-anchor" href="#settings-lost" aria-label="Permalink to &quot;升级后设置不见了 {#settings-lost}&quot;">​</a></h2><p><strong>可能原因</strong></p><ol><li>MeetCue 无法写入程序所在文件夹，把设置保存到了 <code>%APPDATA%\\MeetCue</code>（<a href="/meetcue/zh/troubleshooting/error-codes#mc-sys-002">MC-SYS-002</a>）。</li><li>卸载时使用了 <code>--purge</code>。</li></ol><p><strong>检查</strong></p><ol><li>打开 <strong>设置 › 诊断 › 关于</strong>，查看 <strong>配置目录</strong>。通过 Scoop 安装时应位于 <code>scoop\\persist\\meetcue\\config</code> 下。</li></ol><p><strong>解决</strong></p><ol><li>如果设置在 <code>%APPDATA%\\MeetCue</code> 中，把 <code>settings.json</code> 和 <code>latency-history.json</code> 复制到 persist 文件夹，然后重启 MeetCue。</li><li>API 密钥保存在 Windows 凭据管理器中，升级和卸载都不会丢失。</li></ol><p><strong>仍未解决？</strong> <a href="/meetcue/zh/troubleshooting/diagnostics">导出诊断信息</a>并<a href="https://github.com/Amazingkenneth/meetcue/issues/new?template=bug.yml" target="_blank" rel="noreferrer">提交 Issue</a>。</p>`,42)])])}const u=t(l,[["render",a]]);export{d as __pageData,u as default};
